_CACHE: dict[str, object] = {}


class Task:
    """一条任务。``seq`` 是主键；``tid``/``line`` 是回查图纸用的附属字段。"""

    __slots__ = ("seq", "tid", "line", "case", "subtable", "equation", "roles")

    def __init__(self, seq: int, tid: str, line: int, case: str, subtable: str,
                 equation: str, roles: tuple[str, ...]) -> None:
        self.seq = seq
        self.tid = tid
        self.line = line
        self.case = case
        self.subtable = subtable
        self.equation = equation
        self.roles = roles

    @property
    def arity(self) -> int:
        return self.equation.split("->")[0].count(",") + 1

    def __repr__(self) -> str:                      # pragma: no cover
        return (f"Task(seq={self.seq}, tid={self.tid!r}, line={self.line}, "
                f"case={self.case}, equation={self.equation[:40]!r}…)")


def _tasks() -> tuple[Task, ...]:
    cached = _CACHE.get("tasks")
    if cached is not None:
        return cached
    parsed = []
    for line in _BLOB.splitlines():
        seq, tid, line_no, section, subsection, equation, roles = line.split("\t")
        parsed.append(Task(int(seq), tid, int(line_no), section, subsection,
                           equation, tuple(roles.split(","))))
    tasks = tuple(parsed)
    _CACHE["tasks"] = tasks
    return tasks


def __getattr__(name: str):
    if name == "TASKS":
        return _tasks()
    if name == "N_TASKS":
        return len(_tasks())
    if name == "EQUATIONS":
        return tuple(t.equation for t in _tasks())
    raise AttributeError(name)


def by_seq() -> dict[int, Task]:
    """主键索引：``seq -> Task``。"""
    return {task.seq: task for task in _tasks()}


def by_tid(case: str, subtable: str, tid: str) -> Task | None:
    """按 (情形, 子表, T 号) 精确查（T 号单独不唯一）。"""
    for task in _tasks():
        if task.case == case and task.subtable == subtable and task.tid == tid:
            return task
    return None


def by_section() -> dict[str, int]:
    """按「情形」计数（基础表与附录合并）。"""
    counts: dict[str, int] = {}
    for task in _tasks():
        key = task.case.split(" ")[0] if task.case else "?"
        counts[key] = counts.get(key, 0) + 1
    return counts


def by_case() -> dict[str, list[Task]]:
    groups: dict[str, list[Task]] = {}
    for task in _tasks():
        groups.setdefault(task.case, []).append(task)
    return groups


def base_table_count() -> int:
    """附录起点行号 2805 之前的任务数（基础表 2582 条）。"""
    return sum(1 for task in _tasks() if task.line <= 2805)


def lookup(key):
    """统一查任务：``int`` 视为 seq；``str`` 视为 T 号（可能不唯一，返回首个）。"""
    if isinstance(key, int):
        return by_seq().get(key)
    for task in _tasks():
        if task.tid == key:
            return task
    return None
